import { create } from "@bufbuild/protobuf";
import { describe, expect, it } from "vitest";
import { formatViewCount } from "@/components/MemoDetailSidebar/MemoSharePanel";
import en from "@/locales/en.json";
import { MemoShareSchema } from "@/types/proto/api/v1/memo_service_pb";

const t = ((key: string, options?: Record<string, unknown>) => {
  const template = key.split(".").reduce<unknown>((node, part) => (node as Record<string, unknown> | undefined)?.[part], en);
  return String(template).replace(/\{\{(\w+)\}\}/g, (_m, name: string) => String(options?.[name]));
}) as Parameters<typeof formatViewCount>[1];

describe("formatViewCount", () => {
  it("reads 'N of M views' for a limited share — catches dropping the limit from the text", () => {
    const share = create(MemoShareSchema, { viewLimit: 10, viewCount: 3 });
    expect(formatViewCount(share, t)).toBe("3 of 10 views");
  });

  it("reads 'N views' for an unlimited share — catches showing a limit when none is set", () => {
    const share = create(MemoShareSchema, { viewCount: 3 });
    expect(formatViewCount(share, t)).toBe("3 views");
  });

  it("reads '0 views' for a fresh unlimited share — catches hiding a zero count", () => {
    expect(formatViewCount(create(MemoShareSchema, {}), t)).toBe("0 views");
  });
});
